import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
LOCK = os.path.join(HERE, ".run.lock")
CFG = os.path.join(HERE, "checks.cfg")


def pid_alive(pid):
    if pid <= 0:
        return False
    try:
        os.kill(pid, 0)
    except OSError:
        return False
    return True


def main():
    if os.path.exists(LOCK):
        try:
            pid = int(open(LOCK, encoding="utf-8").read().strip() or "0")
        except ValueError:
            pid = 0
        state = "running" if pid_alive(pid) else "not running"
        sys.stderr.write("ERROR: stale lock checks/.run.lock (pid %d, %s). A previous run left it behind. "
                         "Remove the lock file and re-run.\n" % (pid, state))
        return 2
    if not os.path.exists(CFG):
        sys.stderr.write("ERROR: checks.cfg missing next to run_checks.py\n")
        return 3
    checks = ["imports", "lint", "types", "unit", "schema", "fixtures", "docs"]
    for name in checks:
        print("check %-8s ok" % name)
    print("ALL CHECKS PASSED (%d/%d)" % (len(checks), len(checks)))
    return 0


if __name__ == "__main__":
    sys.exit(main())
